/** A disk-backed model must not rebuild an input-sized dictionary map on the Java heap. */
@Timeout(30)
class SailSourceModelFreshSessionBoundTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("urn:private-spill:predicate");

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void scalarPrivateModelWritesDoNotRetainAnInputSizedFreshSession(boolean inheritedConnectionSession,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setInlineLiterals(false)
				.setBulkOperationSize(64);
		LmdbStore store = new LmdbStore(directory.toFile(), config);
		try (AutoCloseable owner = () -> {
			store.shutDown();
			FileUtil.deleteDir(directory.toFile());
			if (directory.toFile().exists()) {
				throw new IOException("Native test directory remains after successful shutdown: " + directory);
			}
		}) {
			store.init();
			LmdbTestUtil.awaitPostReadyInitialization(store, 10, TimeUnit.SECONDS);
			LmdbSailStore backing = store.getBackingStore();
			if (inheritedConnectionSession) {
				try (LmdbStoreConnection writer = (LmdbStoreConnection) store.getConnection()) {
					writer.begin(IsolationLevels.NONE);
					for (int i = 0; i < 128; i++) {
						writer.addStatement(VF.createIRI("urn:connection:subject:" + i), PREDICATE,
								VF.createLiteral("connection value " + i));
					}
					writer.commit();
				}
				assertThat(backing.hasActiveFreshValueSession())
						.as("a real connection still owns the fresh-import optimization")
						.isTrue();
			}
			try (SailSourceModel model = new SailSourceModel(backing)) {
				for (int i = 0; i < 128; i++) {
					IRI subject = VF.createIRI("urn:private:subject:" + i);
					var value = VF.createLiteral("private spill value " + i);
					assertThat(model.add(subject, PREDICATE, value)).isTrue();
					assertThat(model.contains(subject, PREDICATE, value)).isTrue();
					assertThat(backing.hasActiveFreshValueSession())
							.as("a private model publishes bounded chunks without retaining all assigned values")
							.isFalse();
				}
			}
			try (LmdbStoreConnection reader = (LmdbStoreConnection) store.getConnection()) {
				assertThat(reader.size()).isEqualTo(inheritedConnectionSession ? 256 : 128);
			}
		}
	}
}
